// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.persona.jitimport timber.log.Timberimport android.content.Contextimport android.media.MediaMetadataimport android.media.session.MediaControllerimport android.media.session.MediaSessionManagerimport android.net.Uriimport android.os.BatteryManagerimport android.os.Buildimport android.provider.CallLogimport android.provider.Settings/** * NOUS — JIT Observers (Module 15 v3.0 — Step 15.2). * * Four lightweight observer interfaces that the [JitContextFetcher] calls * **in parallel** during the 300ms STT gap. Each observer is an interface * so tests inject fakes — no Robolectric needed. * * ## Zero battery drain design * * None of these observers run in the background. They are called ONCE when * the wake word fires, return their result in < 50ms, and go dormant. * No wakelocks, no receivers, no periodic polls. */// ──────────────────────────────────────────────────────────────────────────// Battery observer// ──────────────────────────────────────────────────────────────────────────/** * Fetches battery state. No permission required — any app can read * `BatteryManager` via sticky broadcast. */interface BatteryObserver {    /** Get current battery info, or null if unavailable. */    fun fetch(): BatteryInfo?}/** * Android [BatteryObserver] backed by [BatteryManager]. */class AndroidBatteryObserver(    private val context: Context,) : BatteryObserver {    override fun fetch(): BatteryInfo? = try {        val bm = context.getSystemService(Context.BATTERY_SERVICE) as? BatteryManager            ?: return null        val level = bm.getIntProperty(BatteryManager.BATTERY_PROPERTY_CAPACITY)        val charging = bm.isCharging        BatteryInfo(            level = level.coerceIn(0, 100),            isCharging = charging,            isLow = level < LOW_BATTERY_THRESHOLD,        )    } catch (t: Throwable) {        Timber.tag("AndroidBatteryObserver").w("fetch failed", t)        null    }    private companion object {        const val LOW_BATTERY_THRESHOLD = 15    }}// ──────────────────────────────────────────────────────────────────────────// Media observer// ──────────────────────────────────────────────────────────────────────────/** * Fetches currently playing media. Requires `MEDIA_CONTENT_CONTROL` * (restricted — system apps only) OR notification listener access. * * For v1, we use [MediaSessionManager] which works if the app has * notification listener permission. If not, returns null gracefully. */interface MediaObserver {    /** Get currently playing media, or null if nothing playing / no permission. */    fun fetch(): MediaInfo?    /** True if the app has permission to read media sessions. */    fun hasPermission(): Boolean}/** * Android [MediaObserver] backed by [MediaSessionManager]. */class AndroidMediaObserver(    private val context: Context,    private val mediaSessionManager: MediaSessionManager?,    private val notificationListenerComponent: String? = null,) : MediaObserver {    override fun hasPermission(): Boolean {        // MediaSessionManager.getActiveSessions requires the caller to be a        // notification listener OR have MEDIA_CONTENT_CONTROL (system apps).        if (mediaSessionManager == null) return false        val enabledListeners = Settings.Secure.getString(            context.contentResolver,            "enabled_notification_listeners",        ) ?: return false        return notificationListenerComponent != null &&            enabledListeners.contains(notificationListenerComponent)    }    override fun fetch(): MediaInfo? {        if (!hasPermission() || mediaSessionManager == null) return null        return try {            // getActiveSessions requires notification listener or MEDIA_CONTENT_CONTROL.            val component = android.content.ComponentName(                context.packageName,                notificationListenerComponent ?: "",            )            val controllers = mediaSessionManager.getActiveSessions(component)            // Find the first controller that's actually playing.            val playing = controllers.firstOrNull { it.playbackState?.state == 3 /* STATE_PLAYING */ }                ?: return null            val metadata = playing.metadata ?: return null            val track = metadata.getString(MediaMetadata.METADATA_KEY_TITLE) ?: "Unknown"            val artist = metadata.getString(MediaMetadata.METADATA_KEY_ARTIST)                ?: metadata.getString(MediaMetadata.METADATA_KEY_ALBUM_ARTIST)                ?: "Unknown"            val genre = metadata.getString(MediaMetadata.METADATA_KEY_GENRE) ?: "unknown"            MediaInfo(                track = track,                artist = artist,                genre = genre.lowercase(),                packageName = playing.packageName,            )        } catch (t: SecurityException) {            Timber.tag("AndroidMediaObserver").w("Permission denied for media sessions", t)            null        } catch (t: Throwable) {            Timber.tag("AndroidMediaObserver").w("fetch failed", t)            null        }    }}// ──────────────────────────────────────────────────────────────────────────// Call log observer// ──────────────────────────────────────────────────────────────────────────/** * Fetches today's call log summary. Requires `READ_CALL_LOG` permission. */interface CallLogObserver {    /** Get today's call log info, or null if permission not granted. */    fun fetch(): CallLogInfo?    /** True if READ_CALL_LOG permission is granted. */    fun hasPermission(): Boolean}/** * Android [CallLogObserver] backed by [CallLog.Calls] content provider. */class AndroidCallLogObserver(    private val context: Context,) : CallLogObserver {    override fun hasPermission(): Boolean =        context.checkSelfPermission(android.Manifest.permission.READ_CALL_LOG) ==            android.content.pm.PackageManager.PERMISSION_GRANTED    override fun fetch(): CallLogInfo? {        if (!hasPermission()) return null        return try {            val today = System.currentTimeMillis() - (System.currentTimeMillis() % 86_400_000L)            var totalToday = 0            var missedToday = 0            val callersToday = mutableSetOf<String>()            context.contentResolver.query(                CallLog.Calls.CONTENT_URI,                arrayOf(CallLog.Calls.CACHED_NAME, CallLog.Calls.TYPE, CallLog.Calls.DATE),                "${CallLog.Calls.DATE} >= ?",                arrayOf(today.toString()),                "${CallLog.Calls.DATE} DESC",            )?.use { cursor ->                while (cursor.moveToNext()) {                    totalToday++                    val type = cursor.getInt(cursor.getColumnIndexOrThrow(CallLog.Calls.TYPE))                    if (type == CallLog.Calls.MISSED_TYPE) {                        missedToday++                    }                    val name = cursor.getString(cursor.getColumnIndexOrThrow(CallLog.Calls.CACHED_NAME))                    if (!name.isNullOrBlank()) callersToday.add(name)                }            }            // "Frequent contacts who didn't call today" — for v1, we don't have            // a frequent contacts list (that's Module 11: Connectivity). Return            // empty list; Step 15.2 just records the raw data.            CallLogInfo(                totalToday = totalToday,                missedToday = missedToday,                missedFromFrequent = emptyList(),  // populated in Module 11 integration            )        } catch (t: Throwable) {            Timber.tag("AndroidCallLogObserver").w("fetch failed", t)            null        }    }}// ──────────────────────────────────────────────────────────────────────────// Usage stats observer// ──────────────────────────────────────────────────────────────────────────/** * Fetches top app used in the last hour. Requires `PACKAGE_USAGE_STATS` * special access (granted via Settings → Special App Access → Usage Access). */interface UsageStatsObserver {    /** Get top app usage in the last hour, or null if no permission. */    fun fetch(): AppUsageInfo?    /** True if PACKAGE_USAGE_STATS permission is granted. */    fun hasPermission(): Boolean}/** * Android [UsageStatsObserver] backed by [android.app.usage.UsageStatsManager]. */class AndroidUsageStatsObserver(    private val context: Context,) : UsageStatsObserver {    private val usageStatsManager: android.app.usage.UsageStatsManager? by lazy {        context.getSystemService(Context.USAGE_STATS_SERVICE) as? android.app.usage.UsageStatsManager    }    override fun hasPermission(): Boolean {        val appOps = context.getSystemService(Context.APP_OPS_SERVICE) as? android.app.AppOpsManager            ?: return false        val mode = if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.Q) {            appOps.unsafeCheckOpNoThrow(                android.app.AppOpsManager.OPSTR_GET_USAGE_STATS,                android.os.Process.myUid(),                context.packageName,            )        } else {            @Suppress("DEPRECATION")            appOps.checkOpNoThrow(                android.app.AppOpsManager.OPSTR_GET_USAGE_STATS,                android.os.Process.myUid(),                context.packageName,            )        }        return mode == android.app.AppOpsManager.MODE_ALLOWED    }    override fun fetch(): AppUsageInfo? {        // usageStatsManager was already null-checked in hasPermission() above,        // but be defensive — if the system service becomes null (rare edge case        // on some OEM ROMs), return null gracefully instead of crashing with NPE.        val manager = usageStatsManager ?: return null        if (!hasPermission()) return null        return try {            val now = System.currentTimeMillis()            val oneHourAgo = now - 3_600_000L            // queryUsageStats returns List<UsageStats> — call on the non-null manager.            val stats: List<android.app.usage.UsageStats> = manager.queryUsageStats(                android.app.usage.UsageStatsManager.INTERVAL_BEST,                oneHourAgo,                now,            ) ?: return null            val top = stats.maxByOrNull { it.totalTimeInForeground } ?: return null            if (top.totalTimeInForeground == 0L) return null            val appName = try {                val pm = context.packageManager                val info = pm.getApplicationInfo(top.packageName, 0)                pm.getApplicationLabel(info).toString()            } catch (t: Throwable) {                top.packageName            }            AppUsageInfo(                packageName = top.packageName,                appName = appName,                foregroundSeconds = top.totalTimeInForeground / 1000,            )        } catch (t: Throwable) {            Timber.tag("AndroidUsageStatsObserver").w("fetch failed", t)            null        }    }}